void mnt_make_shortterm(struct vfsmount *mnt) /* <=== mnt_make_shortterm */ 
{
#ifdef CONFIG_SMP
	if (atomic_add_unless(&mnt->mnt_longterm, -1, 1))
		return;
	br_write_lock(vfsmount_lock);
	atomic_dec(&mnt->mnt_longterm);
	br_write_unlock(vfsmount_lock);
#endif
}

static inline void mnt_add_count(struct vfsmount *mnt, int n) /* <=== mnt_add_count */ 
{
#ifdef CONFIG_SMP
	this_cpu_add(mnt->mnt_pcp->mnt_count, n);
#else
	preempt_disable();
	mnt->mnt_count += n;
	preempt_enable();
#endif
}

static inline void mnt_dec_count(struct vfsmount *mnt) /* <=== mnt_dec_count */ 
{
	mnt_add_count(mnt, -1);
}

